import * as C from './content.js';
import * as E from './engine.js';
import * as S from './storage.js';
import {render,drawMenu} from './render.js';
import {createInput} from './input.js';
import {createAudio} from './audio.js';
import * as N from './nexus.js';
import {createOnline} from './online.js';
import {createCheckpointWriter} from './checkpoints.js';
import {difficultyCards,rewardCard,hudMarkup,createSelectionGuard} from './presentation.js';

const $=s=>document.querySelector(s),app=$('#app'),canvas=$('#world'),ctx=canvas.getContext('2d');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=x=>Array.isArray(x)?x:Object.values(x||{}),by=(xs,id)=>arr(xs).find(x=>x.id===id)||{id,name:id};
const name=(xs,id)=>by(xs,id).name,fmt=n=>`${Math.floor((n||0)/60)}:${String(Math.floor((n||0)%60)).padStart(2,'0')}`;
const number=n=>Math.round(Number(n)||0).toLocaleString();
let save=S.loadSave(),run=null,page='expedition',catalog='weapons',lastState='',lastHud=0,checkpoint=null,checkpointBusy=false,lastCheckpoint='',summary=null,frames=[],recent=[],errors=[],registration=null;
let launching=false,lastMenuPaint=-Infinity;
const rewardGuard=createSelectionGuard();
let planner={weapons:['pulse'],passives:[],relics:[]};
let setup={mode:'campaign',operator:'nova',biome:'neon-city',difficulty:'standard',...save.selected};
if(setup.arena&&!setup.biome)setup.biome=setup.arena;
let custom={...save.customDifficulty};
let networkRun=false,rankedTicket=null,historySelection=[],ghost=null,lastRoomUI='',networkEdges={dash:false,ability:false},lastNetworkInput=0;
const localPages=['profile','seasons','achievements','history','lore','tutorial'];
const onlinePages=['online','coop','leaderboards','admin'];
const online=createOnline({getSave:()=>save,setSave:async(raw,{backup}={})=>{if(run)throw new Error('Finish or suspend your run before restoring a profile.');const next=S.validateSave(raw);if(backup)download(S.exportSave(save),'nexus-before-cloud-restore.json');await S.clearCheckpoint();checkpoint=null;save=S.saveProfile(next);setup={...save.selected};custom={...save.customDifficulty};applySettings();},onMessage:toast,onRoom:room=>{if(!room&&networkRun){networkRun=false;run=null;page='coop';renderPage();}},onView:(view,room)=>{if(!view)return;if(!networkRun||run?.id!==view.id){summary=null;lastState='';}networkRun=true;run=view;run.coOp=true;if(page!=='settings')page='game';audio.setBiome(run.biome||run.config.biome);syncState();},onChange:state=>{if(!onlinePages.includes(page))return;const signature=JSON.stringify({page,room:state.room,user:state.user,status:state.status,error:state.error,cloud:state.cloudRevision,entries:state.entries,friends:state.friends,requests:state.requests,notices:state.notices,admin:state.admin,profileView:state.profileView});if(signature!==lastRoomUI){lastRoomUI=signature;renderPage();}}});
const checkpoints=createCheckpointWriter({serialize:E.serializeCheckpoint,write:data=>S.saveCheckpoint(data,save),onSaved:data=>{checkpoint=data;},onError:error=>{toast('Checkpoint could not be saved. Keep this tab open and export your profile.');errors.push({message:String(error)});}});
const audio=createAudio(save.settings);
const input=createInput(canvas,{getSettings:()=>save.settings,onPause:reason=>{if($('#dialog').open){if(reason==='toggle')$('#dialog').close();return;}if(!run)return;if(reason==='toggle'||run.state==='playing')gameAction({type:'pause',...(reason==='toggle'?{}:{paused:true})});},onReward:i=>{if(run?.state==='reward'){const c=E.getRewardChoices(run)[i];if(c)actionReward(c.id);}},onMenu:direction=>{const root=$('#dialog').open?$('#dialog'):app;const buttons=[...root.querySelectorAll('button:not(:disabled),select,input,textarea')].filter(b=>b.offsetParent!==null);if(!buttons.length)return;const i=buttons.indexOf(document.activeElement);if(direction==='select'){buttons[Math.max(0,i)].click();return;}buttons[(i+(direction==='next'?1:-1)+buttons.length)%buttons.length].focus();},onDisconnect:()=>{if(run?.state==='playing')gameAction({type:'pause',paused:true});}});
window.addEventListener('error',e=>{errors.push({message:e.message,time:Date.now()});errors=errors.slice(-20);});
window.addEventListener('unhandledrejection',e=>{errors.push({message:String(e.reason),time:Date.now()});toast('Something could not be saved. Export your save from Settings.');});
function persist(){save=S.saveProfile(save);applySettings();}
function applySettings(){document.body.classList.toggle('reduced',!!save.settings.reducedMotion);document.body.classList.toggle('high-contrast',!!save.settings.highContrast);document.documentElement.style.fontSize=(15*(save.settings.uiScale||1))+'px';audio.setSettings(save.settings);if(typeof w!=='undefined')resize();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard');}catch{modal('Copy this text',`<textarea readonly>${esc(text)}</textarea>`);}}
function download(text,filename){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function modal(title,html){if(run?.state==='playing')gameAction({type:'pause',paused:true});input.setMenuActive(true);$('#dialogBody').innerHTML=`<h2>${esc(title)}</h2>${html}<div class="center-actions"><button data-action="close-dialog">Close</button></div>`;if(!$('#dialog').open)$('#dialog').showModal();}
const glyphs=['✦','⬡','ϟ','◇','◆','◉','⌘','❄'];
function header(){const groups=[['EXPLORE',[['expedition','Play','◈'],['leaderboards','Leaderboards','↗'],['coop','Co-op','⌘'],['seasons','Season','✧']]],['YOUR LOADOUT',[['progression','Arsenal','ϟ'],['planner','Build lab','⬡'],['codex','Codex','▤']]],['YOUR JOURNEY',[['profile','Profile','◎'],['achievements','Achievements','◇'],['history','History','↺']]],['SYSTEM',[['online','Account','⊙']]]];if(online.state.user?.role==='admin')groups[3][1].push(['admin','Moderation','⊞']);return `<header><div class="brand"><img src="./assets/v5-icon.svg" alt=""><div>NEON RIFT<small>SURVIVOR / NEXUS V5</small></div></div><nav class="nav" aria-label="Main navigation">${groups.map(([label,items])=>`<div class="nav-group"><span class="nav-label">${label}</span>${items.map(([id,label,icon])=>`<button data-page="${id}" aria-current="${page===id?'page':'false'}" class="${page===id?'active':''}"><span aria-hidden="true" class="nav-icon">${icon}</span>${label}${page===id?'<i aria-hidden="true"></i>':''}</button>`).join('')}</div>`).join('')}</nav><div class="header-tools"><div class="nav-status"><span class="status-dot"></span><div>${online.state.user?esc(online.state.user.username):'Offline ready'}<small>${online.state.user?'Connected to your Nexus':'Your progress stays here'}</small></div></div><button class="header-settings" data-page="settings" aria-label="Settings"><span aria-hidden="true">⚙</span> Settings</button></div></header>`;}
function riftArtwork(){return `<div class="rift-art" aria-hidden="true"><svg viewBox="0 0 500 420" fill="none"><defs><radialGradient id="riftGlow"><stop stop-color="#8b64ff" stop-opacity=".55"/><stop offset="1" stop-color="#8b64ff" stop-opacity="0"/></radialGradient><linearGradient id="riftEdge" x1="80" y1="40" x2="390" y2="370" gradientUnits="userSpaceOnUse"><stop stop-color="#66ffe0"/><stop offset=".5" stop-color="#b59bff"/><stop offset="1" stop-color="#7841ff"/></linearGradient></defs><circle cx="260" cy="204" r="200" fill="url(#riftGlow)"/><g class="rift-orbit"><ellipse cx="260" cy="204" rx="144" ry="162" stroke="url(#riftEdge)" stroke-width="2"/><ellipse cx="260" cy="204" rx="156" ry="177" stroke="#a085ff" stroke-opacity=".3" stroke-dasharray="40 14 3 14"/><ellipse cx="260" cy="204" rx="126" ry="145" stroke="#64ffe1" stroke-opacity=".25"/><path d="M112 131L142 98M365 315L391 281M177 365L202 372" stroke="#90ffe1" stroke-width="4"/></g><path d="M80 309L194 245M326 174L440 110" stroke="#6fffe0" stroke-opacity=".24" stroke-dasharray="5 12"/><g class="rift-ship"><path d="M195 224L336 144L285 279L258 224Z" fill="#0d2433" stroke="#8bffe4" stroke-width="3"/><path d="M195 224L258 224L336 144L232 245Z" fill="#6affd5" fill-opacity=".2" stroke="#8bffe4"/><path d="M232 245L207 273L254 250" fill="#9a7bff"/><path d="M205 265L163 302M195 252L150 278" stroke="#9e80ff" stroke-width="3"/></g><circle cx="396" cy="113" r="4" fill="#8bffe4"/><circle cx="132" cy="301" r="3" fill="#ab8cff"/><path d="M54 75H91M54 75V112M428 334H465M465 297V334" stroke="#67838d" stroke-opacity=".6"/></svg><span class="art-coordinate">SECTOR 05 / RIFT SIGNAL ACTIVE</span></div>`;}

function shell(content){lastMenuPaint=-Infinity;document.body.classList.remove('in-game','combat-active');app.innerHTML=header()+`<main class="hub">${content}<footer class="footer"><span>RIFT NEXUS // V5.0 · <button data-page="tutorial">Field guide</button> <button data-page="lore">Rift archives</button></span><span>LOCAL PROGRESS · ${number(save.cores)} RIFT CORES</span></footer></main>`;input.setMenuActive?.(true);}
function renderPage(){if(run&&page==='game'){renderGameUI();return;}if(localPages.includes(page)){shell(N.renderNexusPage(page,save,{selectedRuns:historySelection,comparison:historySelection,ghost,selectedIds:historySelection}));return;}if(onlinePages.includes(page)){shell(title('The optional Nexus network',page==='coop'?'Enter together':page==='leaderboards'?'Nexus leaderboards':page==='admin'?'Moderation':'Your Nexus account')+online.render(page));return;}if(page==='expedition')renderHub();else if(page==='settings')renderSettings();else if(page==='codex')renderCodex();else if(page==='planner')renderPlanner();else if(page==='progression')renderProgression();else if(page==='records')renderRecords();}
function renderHub(){const op=by(C.OPERATORS,setup.operator),mode=by(C.MODES,setup.mode);shell(`<section class="hero"><div class="hero-copy"><div class="eyebrow">RIFTFALL EXPANSION <span class="hero-badge">V5</span></div><h1>NEON RIFT<br><span>SURVIVOR</span></h1><p>Outnumbered. Overpowered. Unstoppable.<br>Build something the rift has never seen.</p><div class="hero-actions"><button class="primary start-run" data-action="${run&&run.state!=='gameover'?'back-game':'launch'}">${run&&run.state!=='gameover'?'RESUME RUN':'START RUN'} <span aria-hidden="true">↗</span></button>${checkpoint&&!run?'<button data-action="continue">Continue expedition ↻</button>':''}<button data-action="configure">Customize run ↓</button></div><div class="hero-session"><span>${esc(op.name)}</span><span>${esc(mode.name)}</span><span>${esc(setup.mode==='daily'?'Standard':name(C.DIFFICULTIES,setup.difficulty))}</span></div><div class="hero-facts"><span>8 operators</span><span>20 weapons</span><span>Endless possibilities</span></div></div>${riftArtwork()}</section><div class="hub-strip"><span><i class="status-dot"></i> YOUR NEXT EXPEDITION</span><button data-page="tutorial">New here? Learn the controls <span aria-hidden="true">↗</span></button><span class="core-balance">◈ ${number(save.cores)} <small>RIFT CORES</small></span></div>${run?'<div class="alert">Your run is paused. <button data-action="back-game">Resume active run</button></div>':''}${difficultyCards(C.DIFFICULTIES,setup.difficulty,setup.mode==='daily')}<section class="setup"><div class="panel"><div class="panel-head"><span>02 &nbsp; Pick your operator</span><small>8 OPERATORS</small></div><div class="operators">${arr(C.OPERATORS).map((o,i)=>{const unlocked=S.isOperatorUnlocked(save,o.id,setup.mode);return `<button aria-pressed="${setup.operator===o.id}" class="operator ${setup.operator===o.id?'active':''} ${unlocked?'':'locked'}" data-op="${o.id}" style="--op:${o.color||'var(--mint)'}" aria-label="${esc(o.name)}${unlocked?'':' — locked'}" title="${esc(unlocked?o.description:o.unlockDescription||'Unlock through the campaign')}"><span class="sigil">${o.icon||glyphs[i]}</span><b>${esc(o.name.toUpperCase())}</b></button>`;}).join('')}</div><div class="operator-detail"><div class="operator-avatar" style="color:${op.color||'var(--mint)'}">${op.icon||'✦'}</div><div><h3>${esc(op.name)} <small>/ ${esc(op.role||'Rift operator')}</small></h3><p>${esc(op.description||op.desc)}<br>${esc(typeof op.ability==='string'?op.ability:op.ability?.name||'Operator ability')} · ${op.cooldown||24}s cooldown</p></div></div></div><div class="panel"><div class="panel-head"><span>03 &nbsp; Choose the expedition</span><small>6 MODES</small></div><div class="mode-buttons">${arr(C.MODES).map(m=>`<button data-mode="${m.id}" aria-pressed="${setup.mode===m.id}" class="${setup.mode===m.id?'active':''}">${esc(m.name)}</button>`).join('')}</div><p class="mode-detail">${esc(mode.description||mode.desc||'Enter a branching three-act expedition. Every route shapes your build.')}</p><div class="field-row"><label>${setup.mode==='campaign'?'STARTING BIOME':'ARENA'}<select id="biome" ${setup.mode==='campaign'||setup.mode==='daily'?'disabled':''}>${arr(C.BIOMES).map(b=>`<option value="${b.id}" ${b.id===setup.biome?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label></div>${setup.difficulty==='custom'?`<div class="custom-fields">${Object.entries(custom).filter(([key])=>key!=='doubleBosses').map(([k,v])=>`<label>${k} <output>${v}</output><input data-custom="${k}" type="range" min="${C.CUSTOM_RANGES[k][0]}" max="${C.CUSTOM_RANGES[k][1]}" step="${k==='startHp'?10:.1}" value="${v}"></label>`).join('')}</div>`:''}</div></section><details class="advanced-setup"><summary>Fine-tune your build <span>CLASS & SPECIALIZATION</span></summary>${classPanel()}</details><div class="launchbar launch-help"><small>WASD / arrows to move · SPACE to dash · E for ability<br>Six weapons including your starter · Six passives · Three relics</small></div>${registration?.waiting?'<div class="alert">An update is ready. <button data-action="update">Apply update</button></div>':''}`);}
function title(eyebrow,label,extra=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h2>${label}</h2></div>${extra}</div>`;}
function classPanel(){const id=setup.class||'assault',unlocked=save.nexus.xp>=2000||setup.mode==='training';return `<section class="panel class-panel"><div class="panel-head"><span>CLASS & SPECIALIZATION</span><small>BUILD SIDEGRADES</small></div><div class="field-row"><label>CLASS<select id="classSelect" ${setup.mode==='daily'?'disabled':''}>${N.CLASS_DEFINITIONS.map(c=>`<option value="${c.id}" ${id===c.id?'selected':''}>${c.name} · ${c.description}</option>`).join('')}</select></label><label>SUBCLASS<select id="subclassSelect" ${!unlocked||setup.mode==='daily'?'disabled':''}><option value="">${unlocked?'Base specialization':'Unlock at profile level 5'}</option>${N.SUBCLASSES.filter(c=>c.classId===id).map(c=>`<option value="${c.id}" ${setup.subclass===c.id?'selected':''}>${c.name} · ${c.description}</option>`).join('')}</select></label></div><p class="muted">Daily uses a fixed operator, loadout, Assault class, and no Core Grid bonuses.</p>${setup.difficulty==='custom'?`<label><input data-custom="doubleBosses" type="checkbox" ${custom.doubleBosses?'checked':''}> Double bosses</label>`:''}</section>`;}
async function nexusAction(action,button){const id=button.dataset.id;switch(action){
case 'history-select':historySelection=historySelection.includes(id)?historySelection.filter(x=>x!==id):[...historySelection.slice(-1),id];break;
case 'clear-comparison':historySelection=[];break;
case 'favorite-build':save.nexus=N.favoriteBuild(save.nexus,save.history.find(r=>r.id===id));persist();toast('Build saved to your profile');break;
case 'remove-favorite':save.nexus=N.removeFavorite(save.nexus,id);persist();break;
case 'use-favorite':{const build=save.nexus.favoriteBuilds.find(b=>b.id===id);planner={weapons:[...build.weapons],passives:[...build.passives],relics:[...build.relics],operator:build.operator};setup.operator=build.operator;setup.class=build.classId;setup.subclass=build.subclass||'';page='planner';break;}
case 'equip-cosmetic':if(save.nexus.cosmetics.unlocked.includes(id)){save.nexus.cosmetics.equipped=id;persist();}break;
case 'export-ghost':await copy(N.encodeGhost(save.history.find(r=>r.id===id)));break;
case 'import-ghost':modal('Race a recorded score','<p>A ghost compares recorded score pace. Its code is not a verified leaderboard entry.</p><textarea id="ghostCode" placeholder="NRG1.…" aria-label="Ghost code"></textarea><button data-action="confirm-ghost">Load ghost benchmark</button>');return;
case 'clear-ghost':ghost=null;save.nexus.ghosts=[];persist();break;
case 'tutorial-next':save.nexus.tutorial.step=Math.min(6,save.nexus.tutorial.step+1);save.nexus.tutorial.complete=save.nexus.tutorial.step>=6;persist();break;
case 'tutorial-reset':save.nexus.tutorial={step:0,complete:false};persist();break;
case 'tutorial-training':setup.mode='training';await startGame();return;
}renderPage();}
function tutorialEvent(action){const tutorial=save.nexus.tutorial;if(tutorial.complete)return;const step=N.TUTORIAL_STEPS[tutorial.step];if(step?.action===action){tutorial.step++;tutorial.complete=tutorial.step>=N.TUTORIAL_STEPS.length;persist();if(!tutorial.complete)toast(N.TUTORIAL_STEPS[tutorial.step].text);else toast('Field training complete. Welcome to the Nexus.');}}
function downloadResultCard(){const s=summary||save.lastRun;if(!s)throw new Error('Complete a run first.');const weapons=Object.keys(s.weapons||{}).map(id=>name(C.WEAPONS,id));const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="720" viewBox="0 0 1200 720"><defs><linearGradient id="g"><stop stop-color="#073d43"/><stop offset="1" stop-color="#211236"/></linearGradient></defs><rect width="1200" height="720" fill="#070d18"/><path d="M780 0H1200V720H1080L610 240Z" fill="url(#g)"/><rect x="40" y="40" width="1120" height="640" rx="24" fill="none" stroke="#64f6d2" stroke-opacity=".4"/><g font-family="Arial,sans-serif" fill="#edf7ff"><text x="84" y="106" font-size="24" letter-spacing="5" fill="#64f6d2">NEON RIFT / RIFT NEXUS V5</text><text x="84" y="208" font-size="76" font-weight="bold">${number(s.score)} POINTS</text><text x="87" y="261" font-size="25" fill="#abbed1">${esc(s.outcome.toUpperCase())} · ${esc(name(C.OPERATORS,s.operator))} · ${esc(s.mode)} / ${esc(s.difficulty)}</text><text x="87" y="310" font-size="24">${fmt(s.duration)} · ${number(s.kills)} kills · ${number(s.bosses)} bosses ${s.personalBest?'· PERSONAL RECORD':''}</text><text x="87" y="365" font-size="20" fill="#b99cff">${esc(name(C.BIOMES,s.biome))} · ${esc(s.classId||'assault')} ${esc(s.subclass||'')} · Balance ${esc(C.BALANCE_VERSION)}</text><text x="87" y="420" font-size="20">${esc(weapons.slice(0,3).join(' / '))}</text><text x="87" y="454" font-size="20">${esc(weapons.slice(3).join(' / '))}</text><text x="87" y="508" font-size="18" fill="#64f6d2">EVO: ${esc((s.evolutions||[]).map(id=>by(C.WEAPONS,id).evolution?.name||id).join(' / ')||'None')}</text><text x="87" y="550" font-size="18">${esc((s.relics||[]).map(id=>name(C.RELICS,id)).join(' / '))}</text><text x="87" y="626" font-size="18" fill="#abbed1">github.com/dvilrgamerz/Neon-Rift-Survivor · LOCAL RESULT CARD</text></g></svg>`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));a.download='nexus-result.svg';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function renderSettings(){const bools=[['manualAim','Manual aim','Mouse, right stick, or a second touch stick'],['reducedMotion','Reduced motion','Disable shake and major flashing effects'],['reducedFlash','Reduced flash','Use quieter impact and transition effects'],['vibration','Controller vibration','Optional haptic feedback'],['fixedJoystick','Fixed touch stick','Anchor movement at the lower-left safe area'],['screenShake','Screen shake','Impact feedback'],['damageNumbers','Damage numbers','Show damage and status text'],['highContrast','High-contrast warnings','Improve hazard visibility'],['controller','Controller input','Stick navigation and button prompts'],['performance','Performance mode','Lower visual density; identical gameplay'],['diagnostics','Performance overlay','Frame time and entity counters']];shell(title('Make it yours','Settings',run?'<button data-action="back-game">Back to paused run</button>':'')+`<div class="settings-grid"><section class="panel"><h3>Combat & accessibility</h3>${bools.map(([key,label,desc])=>`<div class="setting"><label for="s-${key}">${label}<small>${desc}</small></label><input id="s-${key}" data-setting="${key}" type="checkbox" ${save.settings[key]?'checked':''}></div>`).join('')}</section><section class="panel"><h3>Sound & display</h3><button data-action="fullscreen">Toggle fullscreen ⛶</button>${[['masterVolume','Master volume',0,1,.05],['sfx','Sound effects',0,1,.05],['music','Ambient audio',0,.5,.02],['vfx','Visual effect intensity',0,1,.1],['uiScale','Interface scale',.85,1.3,.05]].map(([key,label,min,max,step])=>`<div class="setting"><label>${label}</label><input aria-label="${label}" data-setting="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${save.settings[key]??1}"></div>`).join('')}<div class="setting"><label>Colour preset<select data-setting="colorblind">${['off','deuteranopia','protanopia','tritanopia'].map(v=>`<option value="${v}" ${save.settings.colorblind===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Visual quality<select data-setting="quality">${['low','medium','high','ultra','auto'].map(v=>`<option value="${v}" ${save.settings.quality===v?'selected':''}>${v}</option>`).join('')}</select></label></div><h3 style="margin-top:25px">Keyboard bindings</h3>${Object.entries(save.settings.keybindings||{}).map(([key,value])=>`<div class="setting"><label>${esc(key)}</label><button data-rebind="${key}">${esc(value.replace('Key',''))}</button></div>`).join('')}<small>Arrow keys always move. Numbers 1–4 choose rewards.</small></section><section class="panel"><h3>Your save, your device</h3><p class="muted">V5 schema · V4 data preserved · Export before changing devices.</p><div class="controls"><button data-action="export">Export save</button><button data-action="import">Import save</button><button data-action="feedback">Report a bug</button></div><div class="controls"><button data-action="whats-new">What’s new in V5</button></div></section><section class="panel"><h3>Controller & touch</h3><p class="muted">Left stick: movement · Right stick: manual aim<br>LB: dash · RB: operator ability · Start: pause<br>D-pad: menu navigation · A: choose<br><br>On touch screens, drag the left side to move. With manual aim on, drag the right side to aim. Use the dash and ability buttons to fight.</p></section></div>`);}
function renderCodex(){const types={weapons:C.WEAPONS,passives:C.PASSIVES,relics:C.RELICS,biomes:C.BIOMES,operators:C.OPERATORS,enemies:C.ENEMIES,events:C.EVENTS};const list=arr(types[catalog]);shell(title('Field intelligence','The Rift Codex')+`<div class="tabs">${Object.keys(types).map(k=>`<button data-catalog="${k}" class="${catalog===k?'active':''}">${k[0].toUpperCase()+k.slice(1)} · ${arr(types[k]).length}</button>`).join('')}</div><div class="grid">${list.map(d=>`<article class="catalog-card"><div class="icon" style="color:${d.color||'var(--mint)'}">${d.icon||'✦'}</div><h3>${esc(d.name)}</h3><p>${esc(d.description||d.desc)}</p>${d.boss?`<p><b>Boss:</b> ${esc(typeof d.boss==='string'?d.boss:d.boss.name)}</p><p>${esc(d.bossDescription||d.hazardDescription||'Phases at 70% and 35% HP. Read warnings before attacks land.')}</p>`:''}${d.evolution?`<p class="compatible">Lv.5 + ${esc(name(C.PASSIVES,d.passive||d.evolution.passive))}<br>→ ${esc(typeof d.evolution==='string'?d.evolution:d.evolution.name)}</p>`:''}${d.unlockDescription?`<p>${esc(d.unlockDescription)}</p>`:''}${d.levels?`<details><summary>Level tuning</summary><p>${d.levels.map((l,i)=>`Lv.${i+1}: ${Object.entries(l).filter(([k,v])=>typeof v==='number').map(([k,v])=>`${k} ${Math.round(v*100)/100}`).join(' · ')}`).join('<br>')}</p></details>`:''}</article>`).join('')}</div>`);}
function renderPlanner(){const groups=[['weapons',C.WEAPONS,6],['passives',C.PASSIVES,6],['relics',C.RELICS,3]];shell(title('Theorycraft your next run','Build Lab','<button data-action="share-build">Copy build code ↗</button>')+`<p class="muted" style="margin-bottom:20px">Plan six weapons, six passives, and three relics. Pulse Blaster occupies the starter slot. Green recipes are compatible.</p>${groups.map(([key,defs,max])=>`<section class="panel" style="margin-bottom:18px"><div class="panel-head"><span>${key} / ${planner[key].length} OF ${max}</span></div><div class="tabs">${arr(defs).map(d=>`<button data-build="${key}:${d.id}" class="${planner[key].includes(d.id)?'active':''}">${esc(d.name)}</button>`).join('')}</div>${key==='weapons'?planner.weapons.map(id=>{const w=by(C.WEAPONS,id),passive=w.passive||w.evolution?.passive;return w.evolution?`<p class="${planner.passives.includes(passive)?'compatible':'muted'}" style="font-size:12px">${esc(w.name)} + ${esc(name(C.PASSIVES,passive))} → ${esc(typeof w.evolution==='string'?w.evolution:w.evolution.name)} ${planner.passives.includes(passive)?'✓':''}</p>`:'';}).join(''):''}</section>`).join('')}<div class="controls"><button data-action="import-build">Import build code</button><button data-action="train-build">Try build in Training</button></div>`);}
function renderProgression(){const trees=[{name:'Assault / Weapon systems',ids:['damage','luck','reroll']},{name:'Vanguard / Survival systems',ids:['health','shield','lifesteal']},{name:'Velocity / Mobility systems',ids:['speed','dodge']}];shell(title('Permanent skills · Cosmetic mastery','The Arsenal',`<span class="pill">${number(save.cores)} CORES AVAILABLE</span>`)+`<p class="muted">Invest Rift Cores across all three systems. Existing purchases are preserved. Daily disables these combat bonuses.</p>${trees.map(tree=>`<section class="panel" style="margin-top:20px"><h3>${tree.name}</h3><div class="grid" style="margin-top:16px">${tree.ids.map(id=>{const n=by(C.CORE_NODES,id),level=save.progression[id]||0,cost=n.cost(level);return `<article class="catalog-card"><div class="icon">${n.icon}</div><h3>${esc(n.name)} <small>${level}/${n.max}</small></h3><p>${esc(n.description)}</p><div class="bar"><i style="width:${level/n.max*100}%"></i></div><button data-core="${id}" ${level>=n.max||save.cores<cost?'disabled':''}>${level>=n.max?'Fully upgraded':`Upgrade · ${cost} cores`}</button></article>`;}).join('')}</div></section>`).join('')}<h2 style="margin:34px 0 22px">Operator mastery</h2><section class="grid">${C.OPERATORS.map(o=>{const m=S.getMastery(save.mastery[o.id]),stats=save.operatorStats[o.id];return `<article class="catalog-card"><h3>${esc(o.name)} <small>MASTERY ${m.level}/10</small></h3><p>${esc(m.title)} · ${esc(m.cosmetic)}</p><p>${number(m.xp)} XP ${m.next?' / '+m.next:' · Complete'} · ${S.isOperatorUnlocked(save,o.id,'campaign')?'Available':esc(o.unlockDescription)}</p><div class="bar"><i style="width:${m.progress*100}%"></i></div><div class="quests">${o.quests.map(q=>`${stats[q.stat]>=q.target?'✓':'◇'} ${esc(q.name)} · ${Math.min(q.target,stats[q.stat]||0)}/${q.target}`).join('<br>')}</div></article>`;}).join('')}</section>`);}
function renderRecords(){const h=save.history||[];shell(title('Your story in the rift','Records & history')+`<div class="summary-grid">${[['Runs',save.stats.runs],['Best score',save.stats.bestScore],['Enemies defeated',save.stats.kills],['Bosses defeated',save.stats.bosses]].map(([n,v])=>`<div class="stat"><b>${number(v)}</b><small>${n}</small></div>`).join('')}</div><section class="panel"><table class="records-table"><thead><tr><th>OPERATOR / MODE</th><th>SCORE</th><th>TIME</th><th>OUTCOME</th></tr></thead><tbody>${h.length?h.slice(0,30).map(r=>`<tr><td>${esc(name(C.OPERATORS,r.operator))}<br><small>${esc(r.mode||r.runMode)} · ${esc(r.difficulty)} · ${esc(r.balanceVersion||'V4 archive')}</small></td><td>${number(r.score)}</td><td>${fmt(r.duration||r.seconds)}</td><td>${esc(r.outcome||r.result)}</td></tr>`).join(''):'<tr><td colspan="4">Your first expedition is waiting. Complete a run to set a record.</td></tr>'}</tbody></table></section>`);}

async function startGame(trainingBuild=false,ranked=false){
 if(launching)return;if(!S.isOperatorUnlocked(save,setup.operator,setup.mode)){toast('Choose an unlocked operator or try Training.');return;}if(networkRun)throw new Error('Leave the co-op room before starting a solo run.');launching=true;input.setMenuActive(true);
 try{audio.play({type:'ui'});app.innerHTML=`<div class="rift-transition" role="status"><div class="transition-sigil" aria-hidden="true">◈</div><strong>ENTERING THE RIFT</strong><span>${esc(name(C.OPERATORS,setup.operator))} / ${esc(name(C.MODES,setup.mode))}</span></div>`;await new Promise(resolve=>setTimeout(resolve,save.settings.reducedMotion?0:480));await createGame(trainingBuild,ranked);}
 catch(error){page='expedition';renderHub();throw error;}
 finally{launching=false;rewardGuard.reset();}
}
async function createGame(trainingBuild=false,ranked=false){if(!S.isOperatorUnlocked(save,setup.operator,setup.mode)){toast('This operator unlocks through campaign milestones. Try them in Training.');return;}if(networkRun)throw new Error('Leave your co-op room before starting a solo run.');await checkpoints.flush();summary=null;rankedTicket=ranked?await online.startRanked({mode:'daily',difficulty:'standard',operator:'nova'}):null;const specialization=N.validateClassSelection(setup.class,setup.subclass,save.nexus,ranked?'daily':setup.mode);const config={...setup,...specialization,cosmetic:save.nexus.cosmetics.equipped,customDifficulty:custom,manualAim:save.settings.manualAim,seed:Date.now()>>>0};if(rankedTicket)Object.assign(config,{mode:'daily',difficulty:'standard',seed:rankedTicket.seed,date:rankedTicket.dailyDate});if(trainingBuild)Object.assign(config,{weapons:planner.weapons,passives:planner.passives,relics:planner.relics});run=E.createRun(config,save);run.id=rankedTicket?.runId||'run-'+crypto.randomUUID();run.ghostSamples=[];if(trainingBuild){run.weapons=Object.fromEntries(planner.weapons.map(id=>[id,5]));run.passives=Object.fromEntries(planner.passives.map(id=>[id,5]));for(const id of planner.relics)if(!run.relics.includes(id))E.equipRelic(run,id);}save.selected={...setup};save.customDifficulty={...custom};persist();page='game';lastState='';checkpoints.reset();audio.setBiome(run.config.biome);await storeBoundary({entry:true});syncState(true);}
async function storeBoundary(options){if(networkRun)return;return checkpoints.capture(run,options);}
function getLoadout(){return `<div class="grid">${[['Weapons',run.weapons,C.WEAPONS],['Passives',run.passives,C.PASSIVES]].map(([label,items,defs])=>`<div class="catalog-card"><h3>${label} ${Object.keys(items).length}/6</h3>${Object.entries(items).map(([id,lv])=>`<p>${esc(name(defs,id))} · Lv.${lv}${run.evolved?.includes(id)?' · EVO':''}</p>`).join('')}</div>`).join('')}<div class="catalog-card"><h3>Relics ${run.relics.length}/3</h3>${run.relics.map(id=>`<p>${esc(name(C.RELICS,id))}</p>`).join('')||'<p>No relics yet</p>'}</div></div>`;}
function baseHud(){return hudMarkup(save.settings.diagnostics);}
function renderGameUI(){document.body.classList.add('in-game');app.innerHTML=baseHud();renderStateOverlay();updateHud();}
function overlay(titleText,sub,body,actions=''){return `<section class="game-overlay state-${run.state}" role="region" aria-label="${esc(titleText)}"><div class="overlay-card"><div class="eyebrow" style="justify-content:center">RIFTFALL / ${esc(run.config.mode.toUpperCase())}</div><h2>${titleText}</h2><p>${sub}</p>${body}<div class="center-actions">${actions}</div></div></section>`;}
function choiceCard(c,attr,index){return rewardCard(c,run,attr,index);}
function renderStateOverlay(){const host=$('#stateOverlay');if(!host)return;input.setMenuActive?.(run.state!=='playing');document.body.classList.toggle('combat-active',run.state==='playing');let html='';if(networkRun&&online.state.room?.you?.spectator&&run.state!=='playing'&&run.state!=='gameover'){html=overlay('Watching the expedition',`The players are ${esc(run.state==='reward'?'choosing upgrades':run.state)}.`, '<p>Choices belong to the two operators.</p>','<button data-action="leave-coop">Leave spectator view</button>');}else if(run.coop?.waitingForOtherPlayer){html=overlay('Your partner is choosing.','The rift is paused while your teammate chooses their reward.','<p>Both players keep their own builds and receive their own rewards.</p>','<button data-action="loadout">Review build</button>');}else if(run.pendingRelic){html=overlay('Make room for a relic',`Replace one relic with ${esc(name(C.RELICS,run.pendingRelic))}.`, `<div class="choice-grid">${run.relics.map(id=>choiceCard({...by(C.RELICS,id),kind:'Replace relic'},`data-replace="${id}"`)).join('')}</div>`);}else if(run.state==='paused'){html=overlay('PAUSED','Take a breath. Your expedition is frozen.','',`<button class="primary" data-action="pause">Resume run</button><button data-action="game-settings">Settings</button><button data-action="feedback">Report a bug</button>${!networkRun&&run.config.mode==='campaign'?'<button data-action="suspend">Save & leave</button>':''}${networkRun?'<button data-action="leave-coop">Leave & reconnect later</button>':''}${networkRun?'':'<button data-action="restart-run">Restart run</button><button data-action="quit-run">Quit to menu</button>'}<button data-action="end-run">End run</button>`);}else if(run.state==='route'){const choices=E.getRouteChoices(run);html=overlay(`Choose your next crossing`, `Act ${run.act||1} / 3 · Encounter ${run.encounter||1} · ${number(run.scrap)} scrap`, `<div class="route-track">${Array.from({length:15},(_,i)=>`<i class="${i<(run.completedEncounters||0)?'done':''}"></i>`).join('')}</div><div class="choice-grid">${choices.map((c,i)=>choiceCard({...c,description:`${name(C.BIOMES,c.biome)} · ${c.description||c.objective} · Danger: ${c.danger||'standard'} · Reward: ${c.reward||'Scrap + upgrade'}`},`data-route="${i}"`)).join('')}</div>`,'<button data-action="loadout">Review build</button><button data-action="suspend">Save & leave</button>');}else if(run.state==='reward'){html=overlay(esc(run.rewardTitle||'Power is a choice.'),'Choose your next advantage. Combat is paused. Six weapons · six passives.',`<div class="choice-grid">${E.getRewardChoices(run).map((c,i)=>choiceCard(c,`data-reward="${esc(c.id)}"`,i)).join('')}</div>`,run.rerolls>0?`<button data-action="reroll">Reroll · ${run.rerolls} left</button>`:'');}else if(run.state==='shop'){html=overlay('The Salvage Exchange',`${number(run.scrap)} scrap available · Purchases last for this run.`,`<div class="choice-grid">${(run.shopItems||[]).map(c=>choiceCard(c,`data-buy="${c.id}" ${c.sold||run.scrap<c.price?'disabled':''}`)).join('')}</div>`,'<button data-action="leave-shop" class="primary">Continue expedition →</button>');}else if(run.state==='event'){html=overlay(run.eventTitle||'A signal in the dark','Read the terms. The rift gives nothing away.',`<div class="choice-grid">${(run.eventChoices||[]).map(c=>choiceCard(c,`data-event="${c.id}"`)).join('')}</div>`);}else if(run.state==='gameover'){html=resultsHTML();}host.innerHTML=html;}
function updateHud(){if(!run||!$('#hudHP'))return;const p=run.player;$('#hudOp').textContent=name(C.OPERATORS,run.config.operator).toUpperCase();$('#hudHP').textContent=`${Math.ceil(p.hp)} / ${Math.ceil(p.maxHp)}`;$('#hudShield').textContent=`${Math.ceil(p.shield||0)} SHIELD`;$('#hpBar').style.width=Math.max(0,p.hp/p.maxHp*100)+'%';$('#shieldBar').style.width=Math.min(100,(p.shield||0)/Math.max(1,p.maxShield||p.shieldMax||50)*100)+'%';$('#hudBiome').textContent=name(C.BIOMES,run.biome||run.config.biome).toUpperCase();$('#hudTime').textContent=fmt(run.time);$('#hudKills').textContent=`${run.kills} KILLS`;$('#hudLevel').textContent=`LEVEL ${run.level}`;$('#hudXP').textContent=`${Math.floor(run.xp)} / ${run.need} XP`;$('#hudScore').textContent=number(run.score);$('#xpBar').style.width=Math.min(100,run.xp/run.need*100)+'%';$('#dashBtn').textContent=`[${save.settings.keybindings.dash.replace('Key','')}] DASH ${p.dashCharges}/${p.dashMax}`;$('#abilityBtn').textContent=`[${save.settings.keybindings.ability.replace('Key','')}] ${p.abilityCooldown>0?Math.ceil(p.abilityCooldown)+'s':'ABILITY READY'}`;$('#objective').textContent=`${run.objective||'Survive the rift'}${run.config.mode==='campaign'?` · ${Math.max(0,(run.objective==='boss'?180:90)-Math.floor(run.encounterTime||0))}s`:''}${run.reactor?` · REACTOR ${Math.ceil(run.reactor.hp)} HP`:''}`;const rival=ghost?N.benchmarkGhost(ghost,run.time):null;if(rival)$('#objective').textContent+=` · GHOST ${number(rival.score)} (${run.score>=rival.score?'+':''}${number(run.score-rival.score)})`;if(run.worldEvent)$('#objective').textContent+=` · ${run.worldEvent.name||run.worldEvent.id}`;if(run.player.downed)$('#objective').textContent='DOWNED · Your teammate must stand beside you for 3 seconds to revive.';if(networkRun&&online.state.room?.you?.spectator)$('#objective').textContent='SPECTATING · '+$('#objective').textContent;if(networkRun&&online.state.status!=='Room connected')$('#objective').textContent+=' · '+online.state.status;if(save.settings.diagnostics&&$('#diagnostic'))$('#diagnostic').textContent=`${Math.round(1000/(frames.reduce((a,b)=>a+b,0)/Math.max(1,frames.length)||16))} FPS · ${number(run.enemies.length)} enemies\n${number(run.bullets.length)} projectiles · ${run.effects.length} effects\n${run.config.biome} / ${save.settings.performance?'performance':'high'} · sim ${simulationMs.toFixed(2)}ms`;}
function resultsHTML(){const s=summary||E.getRunSummary(run),best=Math.max(s.score,...save.history.filter(h=>h.mode===s.mode&&h.difficulty===s.difficulty&&h.balanceVersion===s.balanceVersion&&(!s.date||h.date===s.date)).map(h=>h.score||0));return overlay(s.outcome==='victory'?'RIFT CONQUERED':'GAME OVER',`${esc(s.cause||s.causeOfDeath||'Expedition complete')} · ${esc(name(C.OPERATORS,run.config.operator))}`,`<div class="results-score"><span class="record">${s.newBest?'✦ NEW BEST':'FINAL SCORE'}</span><strong>${number(s.score)}</strong><small>Every fall is a beginning.</small></div><div class="summary-grid">${[['Time survived',fmt(s.duration||run.time)],['Enemies defeated',number(s.kills)],['Level reached',number(run.level)],['Difficulty',name(C.DIFFICULTIES,s.difficulty)],['Best score',number(best)],['Rift cores','+'+number(s.cores)]].map(([k,v])=>`<div class="stat"><b>${esc(v)}</b><small>${k}</small></div>`).join('')}</div><details class="result-details"><summary>Build & combat breakdown</summary><div class="summary-grid">${[['Bosses',s.bosses],['Elites',s.elites],['Damage dealt',s.damageDealt],['HP damage',s.damageTaken],['Shield absorbed',s.shieldAbsorbed],['Mastery XP',s.masteryXp]].map(([k,v])=>`<div class="stat"><b>${number(v)}</b><small>${k}</small></div>`).join('')}</div><div class="panel damage-list"><h3>Damage by weapon</h3>${Object.entries(s.damageByWeapon||run.stats?.damageByWeapon||{}).sort((a,b)=>b[1]-a[1]).map(([id,v])=>`<div class="damage-item"><span>${esc(name(C.WEAPONS,id))}</span><div class="bar"><i style="width:${Math.min(100,v/Math.max(1,s.damageDealt)*100)}%"></i></div><small>${number(v)}</small></div>`).join('')||'<p>No weapon damage recorded.</p>'}</div>${getLoadout()}<div class="controls"><button data-action="copy-run">Copy run</button><button data-action="share-card">Save result card</button><button data-action="feedback">Report a bug</button></div></details>`,`${networkRun?'':'<button class="primary" data-action="play-again">PLAY AGAIN ↗</button><button data-action="change-difficulty">Change difficulty</button>'}<button data-action="return-hub">Main menu</button><button data-action="results-records">Leaderboard</button>`);}
function finish(){if(summary)return;summary=networkRun&&run.summary?{...run.summary}:E.getRunSummary(run);summary.coOp=networkRun;summary.ghostSamples=run.ghostSamples||[];if(online.state.room?.you?.spectator){audio.stop();return;}save=S.finishRun(save,summary);summary={...save.lastRun,newBest:save.lastRun?.personalBest};persist();if(!networkRun){checkpoint=null;checkpoints.flush().then(()=>S.clearCheckpoint()).catch(()=>{});}if(rankedTicket){const ticket=rankedTicket;rankedTicket=null;online.finishRanked(ticket,summary).then(result=>toast(result.status==='accepted'?'Ranked result accepted':'Result queued for review: '+(result.reasons||[]).join(', '))).catch(error=>toast('Ranked result could not be submitted: '+error.message));}audio.stop();}
function syncState(force=false){if(!run||page!=='game')return;const key=run.state+':'+(run.pendingRelic||'')+':'+(run.rewardQueue?.length||0)+':'+(run.rewardChoices||[]).map(c=>c.id).join(',');if(force||key!==lastState){if(run.state==='gameover')finish();if(['route','shop','event','reward'].includes(run.state))storeBoundary().catch(()=>{});if(!$('#stateOverlay'))renderGameUI();else renderStateOverlay();lastState=key;}updateHud();}
function actionReward(id){if(!$('#dialog').open&&run?.state==='reward'&&rewardGuard.take())return gameAction({type:'reward',id});}
async function gameAction(action){try{if(networkRun){await online.roomAction(action);lastState='';syncState(true);return;}if(!run)return;const eventStart=run.events.length;switch(action.type){case 'pause':if(action.paused!==true||run.state==='playing')E.togglePause(run);break;case 'reward':E.selectReward(run,action.id);break;case 'route':E.chooseRoute(run,action.index);await storeBoundary({entry:true});audio.setBiome(run.config.biome);break;case 'replace':E.equipRelic(run,run.pendingRelic,action.replaceId);break;case 'buy':E.buyItem(run,action.id);break;case 'event':E.chooseEvent(run,action.id);break;case 'reroll':E.rerollReward(run);break;case 'abandon':E.abandonRun(run);break;}processEvents(run.events.slice(eventStart));if(action.type==='reward')tutorialEvent('reward');lastState='';syncState();}catch(error){toast(error.message);}}

app.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;audio.play({type:'ui'});try{
if(launching)return;
if(b.dataset.difficulty){setup.difficulty=b.dataset.difficulty;save.selected={...setup};persist();renderHub();return;}
if(b.dataset.page){page=b.dataset.page;renderPage();if(onlinePages.includes(page))await online.refresh(page);return;}
if(b.dataset.onlineAction){await online.handle(b.dataset.onlineAction,b);return;}
if(b.dataset.nexusAction){await nexusAction(b.dataset.nexusAction,b);return;}
if(b.dataset.op){const o=by(C.OPERATORS,b.dataset.op);if(!S.isOperatorUnlocked(save,o.id,setup.mode)){toast(o.unlockDescription||'Nyx: clear act 1 · Echo: clear act 2 · Cryo: win a campaign. All available in Training.');return;}setup.operator=o.id;renderHub();return;}
if(b.dataset.mode){setup.mode=b.dataset.mode;if(!S.isOperatorUnlocked(save,setup.operator,setup.mode))setup.operator='nova';renderHub();return;}
if(b.dataset.catalog){catalog=b.dataset.catalog;renderCodex();return;}
if(b.dataset.route!==undefined){await gameAction({type:'route',index:Number(b.dataset.route)});return;}
if(b.dataset.reward){actionReward(b.dataset.reward);return;}
if(b.dataset.replace){await gameAction({type:'replace',id:run.pendingRelic,replaceId:b.dataset.replace});return;}
if(b.dataset.buy){await gameAction({type:'buy',id:b.dataset.buy});return;}
if(b.dataset.event){await gameAction({type:'event',id:b.dataset.event});return;}
if(b.dataset.build){const [key,id]=b.dataset.build.split(':'),max=key==='relics'?3:6;if(key==='weapons'&&id==='pulse'){toast('Pulse Blaster uses your starter slot.');return;}if(planner[key].includes(id))planner[key]=planner[key].filter(x=>x!==id);else if(planner[key].length<max)planner[key].push(id);else toast(`Maximum ${max} ${key}. Remove one first.`);renderPlanner();return;}
if(b.dataset.core){const n=by(C.CORE_NODES,b.dataset.core),lv=save.progression[n.id]||0,cost=typeof n.cost==='function'?n.cost(lv):(n.baseCost||8)+lv*(n.costStep||5);if(lv<n.max&&save.cores>=cost){save.cores-=cost;save.progression[n.id]=lv+1;persist();renderProgression();}return;}
if(b.dataset.rebind){const action=b.dataset.rebind;b.textContent='Press a key…';window.addEventListener('keydown',function capture(ev){ev.preventDefault();ev.stopImmediatePropagation();if(ev.code==='Escape'){renderSettings();return;}try{const next=structuredClone(save);next.settings.keybindings[action]=ev.code;save=S.saveProfile(next);applySettings();}catch(error){toast(error.message);}renderSettings();},{once:true,capture:true});return;}
await handleAction(b.dataset.action);
}catch(err){toast(err.message||String(err));errors.push({message:String(err),time:Date.now()});}});
document.addEventListener('click',e=>{const b=e.target.closest('#dialog button[data-action]');if(b)handleAction(b.dataset.action).catch(error=>toast(error.message));});
app.addEventListener('change',e=>{const el=e.target;try{if(el.id==='difficulty'){setup.difficulty=el.value;renderHub();}if(el.id==='biome')setup.biome=el.value;if(el.id==='classSelect'){setup.class=el.value;setup.subclass='';renderHub();}if(el.id==='subclassSelect')setup.subclass=el.value;if(el.dataset.setting){const next=structuredClone(save);next.settings[el.dataset.setting]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;save=S.saveProfile(next);applySettings();if(run)run.config.manualAim=save.settings.manualAim;}}catch(error){toast(error.message);renderPage();}});
app.addEventListener('input',e=>{const el=e.target;if(el.dataset.custom){custom[el.dataset.custom]=el.type==='checkbox'?el.checked:Number(el.value);if(el.previousElementSibling?.tagName==='OUTPUT')el.previousElementSibling.value=el.value;}});
async function handleAction(a){switch(a){
case 'configure':$('#difficultySelection')?.scrollIntoView?.({behavior:save.settings.reducedMotion?'instant':'smooth',block:'center'});break;
case 'fullscreen':if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Fullscreen is unavailable in this browser.');break;
case 'launch':if(run&&run.state!=='gameover')throw new Error('Resume, suspend, or end your active run first.');if(checkpoint){modal('Start a new expedition?','<p>Your current checkpoint will be replaced when you start this run.</p><button class="primary" data-action="confirm-launch">Start new run</button>');}else await startGame();break;
case 'ranked-daily':if(run||checkpoint)throw new Error('Finish your active or suspended expedition before a ranked Daily.');await startGame(false,true);break;
case 'reroll':await gameAction({type:'reroll'});break;
case 'share-card':downloadResultCard();break;
case 'confirm-launch':$('#dialog').close();await startGame();break;
case 'continue':{const data=await S.loadCheckpoint();if(!data){toast('No saved expedition found.');checkpoint=null;renderHub();break;}save=S.loadSave();run=E.restoreCheckpoint(data);networkRun=false;page='game';summary=null;lastState='';checkpoints.reset();audio.setBiome(run.config.biome);syncState(true);break;}
case 'pause':await gameAction({type:'pause'});break;
case 'dash':input.trigger('dash');break;
case 'ability':input.trigger('ability');break;
case 'loadout':if(run.state==='playing')await gameAction({type:'pause'});syncState();modal('Your build',getLoadout());break;
case 'game-settings':page='settings';renderSettings();break;
case 'back-game':page='game';lastState='';syncState(true);break;
case 'restart-run':modal('Restart this run?','<p>This expedition will end. Your current build and encounter progress will be lost.</p><button class="primary" data-action="confirm-restart">Restart run</button>');break;
case 'quit-run':modal('Leave this expedition?','<p>This ends your run and records earned progress. You can start fresh from the main menu.</p><button data-action="confirm-quit">Quit to menu</button>');break;
case 'confirm-restart':if(launching)break;if(networkRun){toast('Only solo expeditions can restart here.');break;}$('#dialog').close();await gameAction({type:'abandon'});run=null;summary=null;await startGame();break;
case 'confirm-quit':$('#dialog').close();await gameAction({type:'abandon'});await handleAction('return-hub');break;
case 'play-again':if(launching||run?.state!=='gameover')break;run=null;summary=null;await startGame();break;
case 'change-difficulty':await handleAction('return-hub');$('#difficultySelection')?.scrollIntoView?.({block:'center'});break;
case 'results-records':await handleAction('return-hub');page='records';renderRecords();break;
case 'end-run':modal('End this expedition?','<p>Your current run will end and earned progress will be recorded.</p><button data-action="confirm-end">End run</button>');break;
case 'confirm-end':$('#dialog').close();await gameAction({type:'abandon'});break;
case 'leave-shop':await gameAction({type:'buy',id:'leave'});break;
case 'suspend':if(networkRun)throw new Error('Use the co-op lobby to leave or reconnect.');await storeBoundary();await checkpoints.flush();run=null;page='expedition';audio.stop();renderHub();toast('Expedition saved. Mid-encounter exits restart that encounter.');break;
case 'leave-coop':await online.handle('leave-room');networkRun=false;run=null;summary=null;page='coop';renderPage();break;
case 'return-hub':if(networkRun){await online.handle('leave-room');networkRun=false;}run=null;summary=null;page='expedition';renderHub();break;
case 'copy-run':await copy(`Neon Rift Survivor V5 — Rift Nexus\nScore ${number(summary.score)} | ${name(C.OPERATORS,run.config.operator)} | ${name(C.BIOMES,run.config.biome)} | ${fmt(run.time)}\n${run.kills} kills | ${run.elites} elites | ${run.bosses} bosses | ${run.config.mode} / ${run.config.difficulty}\nWeapons: ${Object.keys(run.weapons).map(id=>name(C.WEAPONS,id)).join(', ')}\nRelics: ${run.relics.map(id=>name(C.RELICS,id)).join(', ')}\nEvolutions: ${run.evolved.join(', ')}\nBalance ${C.BALANCE_VERSION}`);break;
case 'export':download(S.exportSave(save),'neon-rift-v5-save-'+new Date().toISOString().slice(0,10)+'.json');break;
case 'import':if(run)throw new Error('Finish or suspend your run before importing a profile.');modal('Import a save','<p>Import replaces your V5 profile. The original V4 save is preserved. Invalid or incompatible files are rejected.</p><input type="file" id="saveFile" accept="application/json,.json"><div class="controls"><button data-action="confirm-import">Validate & import</button></div>');break;
case 'confirm-import':{if(run)throw new Error('A run is active.');const file=$('#saveFile').files[0];if(!file){toast('Choose a JSON save file.');break;}try{const previous=S.exportSave(save);const next=S.importSave(await file.text());download(previous,'nexus-before-import.json');save=next;await S.clearCheckpoint();checkpoint=null;setup={...save.selected};custom={...save.customDifficulty};applySettings();$('#dialog').close();renderPage();toast('Save imported successfully');}catch(e){toast('Import rejected: '+e.message);}break;}
case 'share-build':await copy(S.encodeBuild({...planner,operator:setup.operator,classId:setup.class,subclass:setup.subclass}));break;
case 'import-build':modal('Import a build','<textarea id="buildCode" aria-label="Build code" placeholder="Paste a Riftfall build code"></textarea><div class="controls"><button data-action="confirm-build">Import build</button></div>');break;
case 'confirm-build':try{planner=S.decodeBuild($('#buildCode').value.trim());setup.operator=planner.operator;setup.class=planner.classId||'assault';setup.subclass=planner.subclass||'';$('#dialog').close();renderPlanner();}catch(e){toast(e.message);}break;
case 'train-build':if(run&&run.state!=='gameover')throw new Error('Finish or suspend the active run first.');setup.mode='training';await startGame(true);break;
case 'feedback':{const data={version:'5.0.0',balanceVersion:C.BALANCE_VERSION,build:run?{weapons:run.weapons,passives:run.passives,relics:run.relics,evolutions:run.evolved}:null,settings:save.settings,counters:run?{enemies:run.enemies.length,projectiles:run.bullets.length,effects:run.effects.length,simulationMs}:null,config:run?.config||setup,state:run?.state||'menu',time:run?.time||0,kills:run?.kills||0,bosses:run?.bosses||0,viewport:`${innerWidth}x${innerHeight}`,online:navigator.onLine,userAgent:navigator.userAgent,frameTime:frames.reduce((a,b)=>a+b,0)/Math.max(1,frames.length),recent:recent.slice(-25),errors:errors.slice(-10)};modal('Report a bug','<p>Review these diagnostics, add what happened, then copy them into a GitHub issue. Nothing is uploaded automatically.</p><textarea id="bugNote" placeholder="What happened? What did you expect?"></textarea><textarea id="bugData" readonly>'+esc(JSON.stringify(data,null,2))+'</textarea><div class="controls"><button data-action="copy-feedback">Copy report</button><button data-action="download-feedback">Download diagnostics</button><a href="https://github.com/dvilrgamerz/Neon-Rift-Survivor/issues/new" target="_blank" rel="noopener">Open GitHub issue ↗</a></div>');break;}
case 'copy-feedback':await copy($('#bugNote').value+'\n\n'+$('#bugData').value);break;
case 'download-feedback':download(JSON.stringify({note:$('#bugNote').value,diagnostics:JSON.parse($('#bugData').value)},null,2),'riftfall-diagnostics.json');break;
case 'whats-new':modal('Welcome to Rift Nexus','<p>Three campaign acts, eight operators, twenty weapons, and fourteen relics.</p><p>V5 adds branching expeditions, dash and abilities, classes, manual aim, distinct bosses, world events, quests, mastery, seasons, and a build lab.</p><p>Optional self-hosted accounts, cloud saves, ranked Daily records, and two-player co-op extend the offline game. No account is required for solo play.</p>');break;
case 'update':if(!run)registration?.waiting?.postMessage('ACTIVATE_UPDATE');break;
case 'confirm-ghost':ghost=N.decodeGhost($('#ghostCode').value.trim());save.nexus.ghosts=[ghost,...save.nexus.ghosts.filter(g=>g.id!==ghost.id)].slice(0,5);persist();$('#dialog').close();page='history';renderPage();break;
case 'close-dialog':$('#dialog').close();break;
}}

let last=performance.now(),acc=0,simulationMs=0,w=0,h=0;
function resize(){lastMenuPaint=-Infinity;w=innerWidth;h=innerHeight;const quality=save.settings.performance?'low':save.settings.quality;const dpr=Math.min(devicePixelRatio||1,quality==='low'?1:quality==='medium'?1.5:quality==='ultra'?3:2);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
window.addEventListener('resize',resize);resize();
let pendingInput={dash:false,ability:false};
function processEvents(events){for(const event of events){audio.play(event);if(event.type==='boss-spawn')toast('WARNING · '+event.name+' has entered the rift');if(event.type==='boss-enrage')toast('ENRAGED · '+event.name+' is escalating its attacks');if(event.type==='dash'||event.type==='ability')input.vibrate?.(event.type==='dash'?40:80);tutorialEvent(event.type==='enemy-defeated'?'kill':event.type);if(['boss-defeated','boss-kill','boss-spawn','boss-phase','evolution','mythic','ability','encounter-complete','death','world-event','quest-complete'].includes(event.type)){recent.push({type:event.type,time:run.time});recent=recent.slice(-50);if(['evolution','mythic','world-event','quest-complete'].includes(event.type))toast(event.name||event.type.toUpperCase());}}}
function frame(now){const elapsed=Math.min(.1,(now-last)/1000);frames.push((now-last)||16);if(frames.length>120)frames.shift();last=now;if(run&&page==='game'){
const sampled=input.sample(run);pendingInput={...sampled,dash:pendingInput.dash||sampled.dash,ability:pendingInput.ability||sampled.ability};if(sampled.x||sampled.y)tutorialEvent('move');
if(networkRun){acc=0;if(now-lastNetworkInput>=50){online.sendInput(pendingInput);pendingInput.dash=false;pendingInput.ability=false;lastNetworkInput=now;}}
else {acc+=elapsed;const start=performance.now();while(acc>=1/60){const ev=E.stepRun(run,pendingInput,1/60);pendingInput.dash=false;pendingInput.ability=false;acc-=1/60;processEvents(Array.isArray(ev)?ev:[]);}simulationMs=performance.now()-start;if(run.time-(run.ghostSamples?.at(-1)?.time??-10)>=10)run.ghostSamples=N.recordGhostSample(run.ghostSamples,run);}
render(ctx,run,{width:w,height:h,settings:save.settings,now});if(now-lastHud>100){syncState();lastHud=now;}
}else{acc=0;pendingInput={dash:false,ability:false};input.sample(null);if(lastMenuPaint===-Infinity||(!save.settings.reducedMotion&&now-lastMenuPaint>=33)){drawMenu(ctx,{width:w,height:h,settings:save.settings,now});lastMenuPaint=now;}}requestAnimationFrame(frame);}
applySettings();checkpoint=await S.loadCheckpoint().catch(()=>null);save=S.loadSave();ghost=save.nexus.ghosts[0]||null;applySettings();renderPage();requestAnimationFrame(frame);online.init();
app.addEventListener('change',event=>{if(event.target.hasAttribute('data-nexus-time'))shell(N.renderNexusPage('history',save,{selectedIds:historySelection,ghost,benchmarkTime:Number(event.target.value)}));});
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(r=>{registration=r;if(r.waiting&&!run)renderPage();r.addEventListener('updatefound',()=>r.installing?.addEventListener('statechange',()=>{if(r.waiting&&!run){toast('An update is ready at the expedition hub.');renderPage();}}));}).catch(()=>{});let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!run&&!reloading){reloading=true;location.reload();}});}


